static inline int
rpc_decode_dhchap_digests(const struct spdk_json_val *val, void *out)
{
	uint32_t *flags = out;
	uint32_t mask = 0;
	enum rpc_dhchap_digest items[32];
	size_t count, i;
	int rc;

	rc = spdk_json_decode_array(val, rpc_decode_dhchap_digest, items,
				    32, &count, sizeof(items[0]));
	if (rc != 0) {
		return rc;
	}

	for (i = 0; i < count; i++) {
		mask |= SPDK_BIT(items[i]);
	}
	*flags = mask;

	return 0;
}

